(()=>{const r=document.querySelector("[data-team]");if(!r||matchMedia("(prefers-reduced-motion: reduce)").matches||!("IntersectionObserver"in window))return;const c=[...r.querySelectorAll("[data-team-tile]")];r.classList.add("team--pre");const i=700;let s=0;const o=new IntersectionObserver(e=>{e.filter(t=>t.isIntersecting).forEach(t=>{o.unobserve(t.target);const a=performance.now(),n=Math.max(a,s);s=n+i,setTimeout(()=>t.target.classList.add("is-play"),n-a)})},{threshold:.45});c.forEach(e=>e.getBoundingClientRect().bottom<0?e.classList.add("is-play"):o.observe(e))})();
